            new() { Id = 7, Title = "Electromagnetism", Code = "PHYS 202", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Lisa Wang", InstructorBio = "Dr. Wang is a theoretical physicist specializing in quantum electrodynamics.", DepartmentId = 3, DepartmentName = "Physics", IsFeatured = false },
            new() { Id = 8, Title = "English Composition", Code = "ENG 101", Description = "Fundamentals of academic writing, critical thinking, and argumentation.", Credits = 3, Schedule = "Mon/Wed 9:00–10:15 AM", InstructorName = "Prof. David Miller", InstructorBio = "Prof. Miller is a published author and writing instructor with expertise in rhetoric and composition.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
            new() { Id = 9, Title = "American Literature", Code = "ENG 250", Description = "Survey of American literary works from the colonial period to the present.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Emily Johnson", InstructorBio = "Dr. Johnson specializes in 20th-century American fiction and has published two books on the subject.", DepartmentId = 4, DepartmentName = "English", IsFeatured = false },
