            new() { Id = 11, Title = "Modern World History", Code = "HIST 102", Description = "Major political, economic, and cultural developments from 1500 to the present.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Rachel Green", InstructorBio = "Dr. Green researches modern European history and the history of international relations.", DepartmentId = 5, DepartmentName = "History", IsFeatured = true }
        };
